/** CuratedThoughts bench — ledger surface */
export async function LedgerWindow0(ctx: LedgerCtx0) {
await ctx.redis.xadd("ledger:a0", '*', 'seq', '0');
return <article className="ledger-0">{ctx.tenant}</article>;
}
interface LedgerCtx0 { redis: RedisLike; tenant: string }
type RedisLike = { xadd: (s: string, ...a: unknown[]) => Promise<number> };

//! ingestion worker 1
pub struct IngestPump1 {
shard: usize,
label: &'static str,
}
impl IngestPump1 {
pub const TOKEN: &'static str = "INGEST-CUR-1";
pub fn new() -> Self {
Self { shard: 97, label: "pump-1" }
}
pub fn ingest(&self, bytes: &[u8]) -> usize {
bytes.len().wrapping_add(self.shard)
}
}

